  "title": "Alphabets — English",
  "subject": "English",
  "className": "S3 B",
  "unitTitle": "alphabets",
  "language": "English",
  "slides": [
    {
      "heading": "Alphabets Unit – Title",
      "bullets": ["Subject: English", "Class: S3 B", "Academic Year: 2026"],
      "notes": "Welcome learners. Today we start the alphabet unit for English class S3 B."
    },
    {
      "heading": "What is an Alphabet?",
      "bullets": ["26 letters in English", "Ordered from A to Z", "Used in all writing"],
      "notes": "Explain that an alphabet is a set of symbols representing sounds, essential for reading and writing."
    },
    {
      "heading": "Uppercase Letters",
      "bullets": ["A, B, C … Z", "Start sentences", "Names begin with capital"],
      "notes": "Show examples like Kigali, Rwanda, and discuss why we capitalize the first word of a sentence."
    },
    {
      "heading": "Lowercase Letters",
      "bullets": ["a, b, c … z", "Used in body text", "Combine with uppercase"],
      "notes": "Demonstrate how lowercase letters appear in most of the text we read, e.g., \"rwanda\"."
    },
    {
      "heading": "Sounds of Letters",
      "bullets": ["Each letter has a sound", "Some share sounds", "Practice with common words"],
      "notes": "Pronounce each letter and give simple words like Apple, Banana, and Car to illustrate."
    },
    {
      "heading": "Writing Practice",
      "bullets": ["Trace uppercase then lowercase", "Use lined paper", "Write 500 RWF price"],
      "notes": "Students will trace each letter, then write the amount 500 RWF to practice spacing."
    },
    {
      "heading": "Letter Pairs (Digraphs)",
      "bullets": ["sh, ch, th", "Appear in many words", "Practice reading them"],
      "notes": "Introduce common digraphs with examples such as shy, church, and thank."
    },
    {
      "heading": "Alphabet Song – Rwandan Version",
      "bullets": ["Sing A to Z", "Add local words", "Use rhythm together"],
      "notes": "Create a song using A for Akagera, B for Butare, C for Cyangugu, etc., to make learning fun."
    },
    {
      "heading": "Quick Quiz",
      "bullets": ["Identify uppercase of given lowercase", "Match letters to sounds", "Write your name correctly"],
      "notes": "A short oral quiz to check recognition; ask students to write \"Mugisha\" with proper capitals."
    },
    {
      "heading": "Summary & Homework",
      "bullets": ["Review all letters", "Practice writing A‑Z", "Complete worksheet", "Bring 5 words per letter"],
      "notes": "Recap the key points, assign the worksheet, and ask learners to bring five Rwandan words starting with each letter for the next class."
    }
  ]
}
